 const userMessages = {};

// ================= CONFIG =================
const runTime = new Date();
const windowHours = 24;
const windowStart = new Date(runTime.getTime() - windowHours * 60 * 60 * 1000);

const options = { timeZone: 'Asia/Karachi', hour12: false };
const PKT_OFFSET = 5 * 60 * 60 * 1000;

const formatPKTime = (ts) =>
  ts ? new Date(ts).toLocaleString('en-GB', options) : null;

const formatDuration = (ms) => {
  if (!ms || ms <= 0) return '0h 0m';
  const totalMinutes = Math.floor(ms / 60000);
  const hours = Math.floor(totalMinutes / 60);
  const minutes = totalMinutes % 60;
  return `${hours}h ${minutes}m`;
};

// ================= TIME EXTRACTOR =================
const extractTimeFromText = (text, msgTimestamp) => {
  const timeMatch = text.match(/(\d{1,2}):(\d{2})\s*(am|pm)?/i);
  if (!timeMatch) return msgTimestamp;

  let hours = parseInt(timeMatch[1]);
  let minutes = parseInt(timeMatch[2]);
  const meridiem = timeMatch[3]?.toLowerCase();

  if (meridiem === 'pm' && hours < 12) hours += 12;
  if (meridiem === 'am' && hours === 12) hours = 0;

  // Get PKT local hour from message timestamp
  const msgLocalTime = new Date(msgTimestamp + PKT_OFFSET);
  const msgHour = msgLocalTime.getUTCHours();
  const msgMinute = msgLocalTime.getUTCMinutes();

  if (!meridiem) {
    if (msgHour >= 12 && hours < 12) {
      const withPM = hours + 12;
      const diffWithPM = Math.abs(withPM * 60 + minutes - (msgHour * 60 + msgMinute));
      const diffWithoutPM = Math.abs(hours * 60 + minutes - (msgHour * 60 + msgMinute));
      if (diffWithPM < diffWithoutPM) hours += 12;
    }
  }

  // Build result timestamp: PKT date + extracted PKT hours → convert to UTC
  const pktDate = new Date(msgTimestamp + PKT_OFFSET);
  const y = pktDate.getUTCFullYear();
  const mo = pktDate.getUTCMonth();
  const d = pktDate.getUTCDate();
  const result = new Date(Date.UTC(y, mo, d, hours - 5, minutes, 0));

  // Safety guards
  if (result.getTime() - msgTimestamp > 60 * 60 * 1000) return msgTimestamp;
  if (msgTimestamp - result.getTime() > 8 * 60 * 60 * 1000) return msgTimestamp;

  return result.getTime();
};

// ================= COLLECT MESSAGES =================
for (const item of $input.all()) {
  const userId = item.json.user;

  const blockText = item.json.blocks?.[0]?.elements?.[0]?.elements?.[0]?.text || '';
  const rawText = blockText || (item.json.text || '');
  const text = rawText.toLowerCase().trim().replace(/\s+/g, ' ');

  const timestamp = Math.floor(Number(item.json.ts) * 1000);
  const msgTime = new Date(timestamp);

  if (msgTime > runTime) continue;

  if (!userMessages[userId]) userMessages[userId] = [];

  userMessages[userId].push({
    text,
    timestamp: msgTime.getTime()
  });
}

// ================= PROCESS USERS =================
const output = [];

for (const userId in userMessages) {

  const messages = userMessages[userId];
  messages.sort((a, b) => a.timestamp - b.timestamp);

  let checkIn = null;
  let checkOut = null;

  let currentStepOut = null;
  const stepPairs = [];

  const allMessages = [];

  for (const msg of messages) {

    const text = msg.text;

    const isCheckIn = /^check[- ]?in/.test(text);
    const isCheckOut = /^check[- ]?out/.test(text);
    const isStepOut = /^step[- ]?out/.test(text);
    const isStepIn = /^step[- ]?in/.test(text);

    let type = 'unknown';
    if (isCheckIn) type = 'check in';
    else if (isCheckOut) type = 'check out';
    else if (isStepOut) type = 'step out';
    else if (isStepIn) type = 'step in';

    allMessages.push({
      type,
      text,
      timestamp: formatPKTime(msg.timestamp)
    });

    if (isCheckIn && !checkIn) {
      checkIn = extractTimeFromText(text, msg.timestamp);
    }

    if (isCheckOut) {
      checkOut = extractTimeFromText(text, msg.timestamp);
    }

    if (isStepOut) {
      if (!currentStepOut) {
        currentStepOut = extractTimeFromText(text, msg.timestamp);
      }
    }

    if (isStepIn) {
      if (currentStepOut) {
        stepPairs.push({
          stepOut: currentStepOut,
          stepIn: extractTimeFromText(text, msg.timestamp)
        });
        currentStepOut = null;
      }
    }
  }

  // ================= BREAK CALCULATION =================
  let totalBreak = 0;

  for (const p of stepPairs) {
    totalBreak += (p.stepIn - p.stepOut);
  }

  if (currentStepOut) {
    const ONE_HOUR = 60 * 60 * 1000;
    totalBreak += ONE_HOUR;
  }

  // ================= WORKING HOURS =================
  let workingFormatted = 'N/A';

  if (checkIn) {
    const effectiveOut =
      checkOut || messages[messages.length - 1].timestamp;

    let working = (effectiveOut - checkIn) - totalBreak;
    if (working < 0) working = 0;
    workingFormatted = formatDuration(working);
  }

  // ================= STATUS =================
  let status = 'Absent';

  if (checkIn && checkOut) {
    status = 'Complete';
  } else if (checkIn && !checkOut) {
    status = 'Missing Check-out';
  } else if (!checkIn && checkOut) {
    status = 'Missing Check-in';
  }

  // ================= OUTPUT =================
  output.push({
    json: {
      userId,
      date: new Date(windowStart).toLocaleDateString('en-GB', options),
      windowStart: formatPKTime(windowStart),
      windowEnd: formatPKTime(runTime),

      checkInTime: formatPKTime(checkIn),
      checkOutTime: formatPKTime(checkOut),

      totalWorkingHours: workingFormatted,
      totalBreakDuration: formatDuration(totalBreak),

      status,
      totalMessages: messages.length,
      allMessages
    }
  });
}

return output;

