    ...record.json,
    checkInTime: convertToAMPMWithDate(record.json.checkInTime),
    checkOutTime: convertToAMPMWithDate(record.json.checkOutTime),
    userName: userProfile ? (userProfile.real_name || userProfile.name) : "Unknown User",
    userRealName: userProfile ? userProfile.real_name : null,
    userDisplayName: userProfile?.profile?.display_name || null,
    totalWorkingHours: record.json.totalWorkingHours || null,
    totalBreakDuration: record.json.totalBreakDuration || null
  });
}

// Add missing tracked users with Absent status
for (const userId of trackedUserIds) {
  if (!existingUserIds.has(userId)) {
    const userProfile = userProfileMap.get(userId);
    result.push({
      userId: userId,
      userName: userProfile ? (userProfile.real_name || userProfile.name) : "Unknown User",
      userRealName: userProfile ? userProfile.real_name : null,
      userDisplayName: userProfile?.profile?.display_name || null,
      date: new Date().toLocaleDateString('en-GB'),
      windowStart: null,
      windowEnd: null,
      checkInTime: null,
      checkOutTime: null,
      totalMessages: 0,
      status: "Absent",
      totalWorkingHours: null,
      totalBreakDuration: null
    });
  }
}

return result;

 const results = [];

// USER SHIFT CONFIG (USER ID BASED) 
const userShifts = {

   "U08U4Q2MZHD" : { start: 17, end: 2 }, // Abdul Ahad 
  "U0ASMRUE7RV" : { start: 13, end: 22 }, // M.Jawad
  "U0B1MUQKU8M": { start: 13, end: 22 }, // Laiba Batool
  "U0B2APRLXKN": { start: 13, end: 22 }, // Ali Javed
  "U0BC2T9HE5R" : { start: 13, end: 22 }, // Ahmad Javed
  "U0BEK054LSG": { start: 16, end: 22 }, // Ahmed Makki
  "U0BFF9EGX41": { start: 16, end: 22 } // Muhammad Ahmed  

};

// ================= MAIN LOOP =================
for (const item of $input.all()) {

  const userName = item.json.userName;
  const userId = item.json.userId;
  const date = item.json.date;
  const checkInTime = item.json.checkInTime;
  const checkOutTime = item.json.checkOutTime;
  const totalBreakDuration = item.json.totalBreakDuration;

  let status = 'On Time';

  // ===== TIME PARSER =====
  const parseTime = (str) => {
    if (!str) return null;
    const [datePart, timePart] = str.split(', ');
    const [day, month, year] = datePart.split('/');
    return new Date(`${month}/${day}/${year}, ${timePart}`);
  };

  const toMinutes = (date) => date.getHours() * 60 + date.getMinutes();

  const formatMinutes = (mins) => {
    const h = Math.floor(mins / 60);
    const m = mins % 60;
    return `${h}h ${m}m`;
  };

  // ===== SHIFT FORMATTER =====
  const formatShiftHour = (hourDecimal) => {

    const hour = Math.floor(hourDecimal);
    const minutes = (hourDecimal % 1) * 60;

    const dateObj = new Date();
    dateObj.setHours(hour, minutes, 0);

    return dateObj.toLocaleTimeString('en-US', {
      hour: 'numeric',
      minute: '2-digit',
      hour12: true
    });
  };

  // ===== BREAK PARSER =====
  const parseBreak = (str) => {
    if (!str || str === '0h 0m') return 0;
    const match = str.match(/(\d+)h\s*(\d+)m/);
    if (!match) return 0;
    return parseInt(match[1]) * 60 + parseInt(match[2]);
  };

  const shift = userShifts[userId];

  // ===== SHIFT DISPLAY =====
  let shiftDisplay = '-';

  if (shift) {
    shiftDisplay = `${formatShiftHour(shift.start)} - ${formatShiftHour(shift.end)}`;
  }

  // ===== STATUS LOGIC =====
  if (!checkInTime) {

    status = 'Absent';

  } else {

    const checkInDate = parseTime(checkInTime);
    const checkInMinutes = toMinutes(checkInDate);

    // Default fallback shift = 1 PM
    const shiftStartHour = shift ? shift.start : 13;

    const lateThreshold = (shiftStartHour * 60) + 15;

    if (checkInMinutes >= lateThreshold) {
      status = 'Late';
    }
  }

  // ===== BREAK + WORK HOURS =====
  let breakDisplay;
  let workHoursDisplay;

  if (status === 'Absent') {

    breakDisplay = '-';
    workHoursDisplay = '-';

  } else {

    const breakMinutes = parseBreak(totalBreakDuration);

    // ===== BREAK DISPLAY =====
    if (!totalBreakDuration || breakMinutes === 0) {
      breakDisplay = 'No Break';
    } else {
      breakDisplay = totalBreakDuration;
    }

    // ===== WORK HOURS =====
    let totalMinutes = 0;

    if (checkInTime) {

      const checkInDate = parseTime(checkInTime);

      let endTime;

      if (!checkOutTime) {

        endTime = new Date(checkInDate);

        if (shift) {

          if (shift.end > shift.start) {
            // Same day shift
            endTime.setHours(shift.end, 0, 0, 0);
          } else {
            // Overnight shift
            endTime.setDate(endTime.getDate() + 1);
            endTime.setHours(shift.end, 0, 0, 0);
          }

        } else {
          // fallback shift
          endTime.setHours(22, 0, 0, 0);
        }

      } else {

        endTime = parseTime(checkOutTime);

        // Handle next-day checkout
        if (endTime < checkInDate) {
          endTime.setDate(endTime.getDate() + 1);
        }
      }

      totalMinutes = Math.floor((endTime - checkInDate) / 60000);

      // 🔥 SUBTRACT BREAK
      totalMinutes = Math.max(0, totalMinutes - breakMinutes);

      workHoursDisplay = formatMinutes(totalMinutes);

    } else {
      workHoursDisplay = '0h 0m';
    }
  }

  // ===== FINAL OUTPUT =====
  results.push({
    json: {
      Name: userName,
      "Shift Time": shiftDisplay,
      Date: date,
      "Check-In": checkInTime || '-',
      "Check-Out": checkInTime ? (checkOutTime ? checkOutTime : '(M)') : '-',
      "Work Hours": workHoursDisplay,
      Break: breakDisplay,
      Status: status
    }
  });
}

return results; 

